import"./scan_settings_section.js";import"./strings.m.js";import{strictQuery}from"chrome://resources/ash/common/typescript_utils/strict_query.js";import{I18nMixin}from"chrome://resources/cr_elements/i18n_mixin.js";import{PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{getTemplate}from"./scan_to_select.html.js";import{ScanningBrowserProxyImpl}from"./scanning_browser_proxy.js";const ScanToSelectElementBase=I18nMixin(PolymerElement);class ScanToSelectElement extends ScanToSelectElementBase{static get is(){return"scan-to-select"}static get template(){return getTemplate()}static get properties(){return{disabled:Boolean,selectedFolder:{type:String,notify:true},selectedFilePath:{type:String,notify:true}}}constructor(){super();this.browserProxy=ScanningBrowserProxyImpl.getInstance();this.selectedFolder=this.i18n("myFilesSelectOption");this.browserProxy.initialize()}onSelectFolder(){this.browserProxy.requestScanToLocation().then((selectedPath=>{strictQuery("#scanToSelect",this.shadowRoot,HTMLSelectElement).selectedIndex=0;const baseName=selectedPath.baseName;const filePath=selectedPath.filePath;if(!baseName||!filePath){return}this.selectedFolder=baseName;this.selectedFilePath=filePath}))}}customElements.define(ScanToSelectElement.is,ScanToSelectElement);